_N = {k: i + 1 for i, k in enumerate(_REFS)}


def r(*keys):
    return "".join(f'<sup><a href="#ref{_N[k]}">{_N[k]}</a></sup>' for k in keys)


SHAHAM = "https://www.gov.il/BlobFolder/reports/defending-against-the-cold-subtropical/he/Professional_information_defending-against-the-cold-subtropical-2025.pdf"
